begin;
set local search_path=public,extensions;
select plan(31);

select ok((select count(*)=8 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['franchises','franchise_territory_versions','franchise_mandate_versions','franchise_invitations','franchise_invitation_versions','franchise_approval_requests','franchise_approval_decisions','franchise_governance_events'])),'all franchise governance tables exist');
select ok((select count(*)=8 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['franchises','franchise_territory_versions','franchise_mandate_versions','franchise_invitations','franchise_invitation_versions','franchise_approval_requests','franchise_approval_decisions','franchise_governance_events'])),'RLS is enabled on every franchise governance table');
select ok((select count(*)=8 from pg_policies where schemaname='public'and tablename=any(array['franchises','franchise_territory_versions','franchise_mandate_versions','franchise_invitations','franchise_invitation_versions','franchise_approval_requests','franchise_approval_decisions','franchise_governance_events'])),'each governance table has one scoped read policy');
select ok((select count(*)=3 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['propose_franchise_governance','decide_franchise_governance','accept_franchise_invitation'])),'three commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['propose_franchise_governance','decide_franchise_governance','accept_franchise_invitation'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anon and service roles cannot execute user commands');
select ok((select count(*)=3 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['propose_franchise_governance','decide_franchise_governance','accept_franchise_invitation'])),'authenticated has explicit command execution');
select ok(not has_table_privilege('authenticated','public.franchises','INSERT')and not has_table_privilege('authenticated','public.franchise_mandate_versions','UPDATE')and not has_table_privilege('authenticated','public.franchise_approval_decisions','DELETE'),'authenticated cannot mutate governance tables directly');
select ok(not has_table_privilege('service_role','public.franchises','INSERT')and not has_table_privilege('service_role','public.franchise_mandate_versions','UPDATE'),'service role has no direct governance mutation bypass');
select ok(to_regclass('private.franchise_invitation_tokens')is not null and not has_table_privilege('authenticated','private.franchise_invitation_tokens','SELECT')and not has_table_privilege('service_role','private.franchise_invitation_tokens','SELECT'),'invitation token hashes remain in a private non-readable store');
select ok((select count(*)=5 from pg_trigger where tgname=any(array['franchise_territories_immutable','franchise_mandates_immutable','franchise_invitation_versions_immutable','franchise_approval_decisions_immutable','franchise_governance_events_immutable'])and not tgisinternal),'territories, mandates, invitation versions, decisions and event history are immutable');
select ok((select data_type='bigint'from information_schema.columns where table_schema='public'and table_name='franchise_mandate_versions'and column_name='entry_fee_minor'),'entry fee uses exact minor units');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name like'franchise%'and data_type in('real','double precision')),'franchise governance has no floating-point financial column');
select ok((select count(*)=3 from information_schema.columns where table_schema='public'and table_name='franchise_mandate_versions'and column_name in('franchisee_share_bps','neoxa_share_bps','matricia_share_bps')and data_type='integer'),'economic shares use integer basis points');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and indexname='franchises_active_library_territory_uidx'and indexdef like'%WHERE (status = ''ACTIVE''%'),'one active franchise per library and configured territory is enforced');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and indexname='franchise_mandates_one_active_uidx'),'one active mandate version per franchise is enforced');
select ok(exists(select 1 from pg_constraint where conrelid='public.franchises'::regclass and contype='c'and pg_get_constraintdef(oid)like'%operator_code%'and pg_get_constraintdef(oid)like'%HATIM_AHMITECH%'),'IT operator is structurally bound to Hatim Ahmitech');
select ok((select pg_get_functiondef(p.oid)like'%p_entry_fee_minor<>0%'and pg_get_functiondef(p.oid)like'%p_entry_fee_mode<>''EXEMPT''%'and pg_get_functiondef(p.oid)like'%p_entry_fee_term_months<>0%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='propose_franchise_governance'),'IT entry fee is strictly zero, exempt and has no schedule');
select ok((select pg_get_functiondef(p.oid)like'%HATIM_AHMITECH%'and pg_get_functiondef(p.oid)like'%franchise_economic_rule_versions%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='propose_franchise_governance'),'proposal binds Hatim and a versioned economic rule');
select ok((select franchisee_share_bps=5000 and neoxa_share_bps=5000 and matricia_share_bps=0 and entry_fee_minor=0 from public.franchise_economic_rule_versions where franchise_type='IT'and status='ACTIVE'order by version desc limit 1),'active IT rule is 50 percent Hatim, 50 percent Jalil-NEOXA, zero Asma and zero entry fee');
select ok((select franchisee_share_bps=5000 and neoxa_share_bps=2500 and matricia_share_bps=2500 from public.franchise_economic_rule_versions where franchise_type='STANDARD'and status='ACTIVE'order by version desc limit 1),'active default standard rule is 50/25/25');
select ok((select pg_get_functiondef(p.oid)like'%p_entry_fee_term_months not between 1 and 6%'and pg_get_functiondef(p.oid)like'%REVENUE_WITHHOLDING%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='propose_franchise_governance'),'ordinary franchise installment and withholding schedules are capped at six months');
select ok((select pg_get_functiondef(p.oid)like'%a=q.requested_by%'and pg_get_functiondef(p.oid)like'%FRANCHISE_APPROVAL_DENIED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_franchise_governance'),'maker cannot approve their own franchise proposal');
select ok((select pg_get_functiondef(p.oid)like'%SUPER_ADMIN%'and pg_get_functiondef(p.oid)like'%MATRICIA_ADMIN%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_franchise_governance'),'central roles control the approval decision');
select ok((select pg_get_functiondef(p.oid)like'%FRANCHISE_CENTRAL_APPROVAL_REQUIRED%'and pg_get_functiondef(p.oid)like'%FRANCHISE_OWNER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='accept_franchise_invitation'),'activation requires central approval and acceptance by the franchise owner');
select ok((select pg_get_functiondef(p.oid)like'%status=''ACTIVE''%'and pg_get_functiondef(p.oid)like'%current_mandate_version_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='accept_franchise_invitation'),'acceptance activates the franchise and pins an immutable mandate version');
select ok((select pg_get_functiondef(p.oid)like'%FranchiseApprovalRequiredV1%'and pg_get_functiondef(p.oid)like'%event_outbox%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='propose_franchise_governance'),'proposal emits a versioned Outbox event');
select ok((select pg_get_functiondef(p.oid)like'%FranchiseApprovedV1%'and pg_get_functiondef(p.oid)like'%FranchiseRejectedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_franchise_governance'),'approval and rejection emit explicit events');
select ok((select pg_get_functiondef(p.oid)like'%FranchiseActivatedV1%'and pg_get_functiondef(p.oid)like'%franchise.activated%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='accept_franchise_invitation'),'activation is audited and emitted through Outbox');
select ok((select pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%finish_contract_command%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='propose_franchise_governance'),'proposal uses canonical idempotency');
select ok((select pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%finish_contract_command%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_franchise_governance'),'decision uses canonical idempotency');
select ok((select count(*)>=5 from pg_indexes where schemaname='public'and tablename=any(array['franchises','franchise_territory_versions','franchise_mandate_versions','franchise_invitations','franchise_approval_requests','franchise_governance_events'])),'territory, mandate, invitation, approval and timeline access paths are indexed');

select * from finish();
rollback;
